 * Uses the spatial index cell for O(1)-ish lookup instead of scanning all entities.
 * Stale entries are cleaned lazily.
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} x
 * @param {number} y
 * @returns {number[]}
