      _removeFromCell(st, key, id);
      st.entityCell.delete(id);
      continue;
    }
    const pos = world.get(id, Position);
    if (!pos) {
      _removeFromCell(st, key, id);
      st.entityCell.delete(id);
      continue;
    }
    _syncEntityCell(st, id, pos);
    if (pos.x === x && pos.y === y) result.push(id);
