function capacityStackKey(world, itemId) {
  if (!(itemId > 0) || !world.isAlive(itemId)) return `__dead_${itemId}`;
  const ni = world.get(itemId, NamedIdentity);
  const base = ni?.identity ? String(ni.identity) : `__entity_${itemId}`;
