  const noonAmbient = computeAmbient({
    isOverworld: true,
    turnInDay: 365,
    moonBrightness: 0.15,
  });
  const nightAmbient = computeAmbient({
    isOverworld: true,
    turnInDay: 0,
    moonBrightness: 0.15,
  });

